"""Export measured object-point targets, with failures excluded from training."""
import argparse,hashlib,json,subprocess,sys
from itertools import product
from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('directory',type=Path);args=p.parse_args();r=args.directory
initial=json.load(open(r/'initial.json'));result=json.load(open(r/'result.json'));assets=np.load(r/'meshes.npz');frames=np.load(r/'physics-frames.npz');times=frames['seconds'];body_paths=list(assets['body_paths']);held=[x for x in result['lift_evidence'] if x['lift_m']>=.065 and x['hold_drift_m']<.003 and min(x['tip_contact_force_N'])>.001];brick=str(held[0]['brick']) if held else initial['selected'];body_index=body_paths.index(initial['brick_paths'][brick]);points=np.array([[x,y,z] for x,y,z in product([-.008,.008],[-.016,.016],[0,.0096])]+[[0,0,.0048]]);brick_indices=[body_paths.index(path) for path in initial['brick_paths'].values()];trajectory=frames['poses'][:,brick_indices,:3,3];scene_valid=bool(np.isfinite(trajectory).all() and trajectory[:,:,2].min()>-.002 and abs(trajectory).max()<1.);indices=np.unique(np.round(np.linspace(0,len(times)-12,8)).astype(int));split='source_train' if 30010<=initial['seed']<=30017 else ('heldout_hand_scenes' if initial['seed'] in [30018,30019] else 'development');examples=[]
for index in indices:
 future=int(np.argmin(abs(times-(times[index]+.5))));a=frames['poses'][index,body_index];b=frames['poses'][future,body_index];current=points@a[:3,:3].T+a[:3,3];next_points=points@b[:3,:3].T+b[:3,3];examples.append({'seed':initial['seed'],'split':split,'frame':int(index),'image':f'frame-{index:04}.png','camera_file':'image-render.json','brick':brick,'source_embodiment':'Shadow Hand','input':'RGB image and camera calibration only; no future poses','supervision':{'point_frame':'world metres','local_points_m':points.tolist(),'current_points_world_m':current.tolist(),'next_points_world_m':next_points.tolist(),'displacement_world_m':(next_points-current).tolist(),'horizon_s':float(times[future]-times[index])},'attempt_success':result['success'],'eligible_for_successful_demonstration_training':bool(held) and scene_valid and split=='source_train','scene_valid':scene_valid})
(r/'object-motion.json').write_text(json.dumps({'controller':result['controller'],'source_pose_sha256':hashlib.sha256((r/'physics-frames.npz').read_bytes()).hexdigest(),'contact_gate':'65mm lift, under3mm drift over1second, bilateral contacts','scene_valid':scene_valid,'training_status':'Not trained; failed or unstable attempts are excluded','examples':examples},indent=2));subprocess.run([sys.executable,str(Path(__file__).with_name('render.py')),str(r),'--indices',','.join(map(str,indices)),'--width','512'],check=True);print(json.dumps({'seed':initial['seed'],'examples':len(examples),'success':bool(held)}))
